1	package credit
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"path/filepath"
10	)
11	
12	// recordVersion 是当前记录文件格式版本。
13	const recordVersion = 1
14	
15	// fileData 是记录文件的磁盘格式。
16	type fileData struct {
17		Version       int            `json:"version"`
18		Courses       []*Course      `json:"courses"`
19		Students      []*Student     `json:"students"`
20		Requirements  []*Requirement `json:"requirements"`
21		Enrollments   []*Enrollment  `json:"enrollments"`
22		Waivers       []*Waiver      `json:"waivers"`
23		NextResultSeq int            `json:"nextResultSeq"`
24	}
25	
26	// Load 从 path 读取记录。
27	//
28	// 文件不存在时返回空记录集，existed=false，且不报错——即“从空记录开始”。
29	// 文件存在但无法读取（权限、I/O 错误等）或内容损坏（非法 JSON、结构矛盾、
30	// 引用悬空等）时返回错误，调用方绝不应把该文件当作空记录覆盖写入。
31	// 空文件同样视为损坏，而不是空记录。
32	//
33	// 整份文件必须只含一条完整记录：记录前后允许空白（空格、制表符、换行、
34	// 回车），但完整记录结束后只要还有任何内容——多出的右花括号或右方括号、
35	// 拼接的第二段 JSON、普通文字或没写完的 JSON 片段——都判为损坏并拒绝读取，
36	// 绝不依据已读到的前半条记录继续办理业务。
37	func Load(path string) (s *Store, existed bool, err error) {
38		f, err := os.Open(path)
39		if err != nil {
40			if errors.Is(err, os.ErrNotExist) {
41				return NewStore(), false, nil
42			}
43			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
44		}
45		defer f.Close()
46	
47		fi, err := f.Stat()
48		if err != nil {
49			return nil, false, fmt.Errorf("无法读取记录文件 %s 的信息：%w", path, err)
50		}
51		if fi.Size() == 0 {
52			return nil, true, fmt.Errorf("记录文件 %s 存在但为空，内容已损坏，未做任何修改", path)
53		}
54	
55		var data fileData
56		dec := json.NewDecoder(f)
57		dec.DisallowUnknownFields()
58		if err := dec.Decode(&data); err != nil {
59			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（JSON 解析失败：%v），未做任何修改", path, err)
60		}
61		// 完整记录之后必须只剩下空白：再解一条原始 JSON，仅 io.EOF 表示记录后
62		// 别无他物。不能用 dec.More() 判断——它只向前看“值起始”标记，记录后
63		// 多出的右花括号/右方括号会让 More() 直接返回 false 而被漏掉。再次
64		// Decode 能覆盖全部情形：成功读到值说明后面拼接了第二段 JSON；返回
65		// 语法错误或 unexpected EOF 说明尾部有孤立括号、普通文字或未写完的
66		// 片段。这些一律视为文件损坏。
67		var extra json.RawMessage
68		switch err := dec.Decode(&extra); {
69		case errors.Is(err, io.EOF):
70			// 唯一一份完整记录之后只有空白，符合格式。
71		case err == nil:
72			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后还拼接了其他 JSON 数据），未做任何修改", path)
73		default:
74			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后仍有无法解析的多余内容），未做任何修改", path)
75		}
76	
77		s = NewStore()
78		if err := s.loadData(&data); err != nil {
79			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（%v），未做任何修改", path, err)
80		}
81		return s, true, nil
82	}
83	
84	// loadData 校验磁盘数据并重建索引；任何矛盾都作为损坏报错。
85	func (s *Store) loadData(d *fileData) error {
86		if d.Version != recordVersion {
87			return fmt.Errorf("不支持的记录版本 %d（当前支持版本 %d）", d.Version, recordVersion)
88		}
89	
90		// 课程
91		for _, c := range d.Courses {
92			if c == nil {
93				return errors.New("存在空的课程记录")
94			}
95			if c.ID == "" {
96				return errors.New("存在没有编号的课程")
97			}
98			if c.Name == "" {
99				return fmt.Errorf("课程 %s 没有名称", c.ID)
100			}
101			if c.Credit <= 0 {
102				return fmt.Errorf("课程 %s 学分不是正整数：%d", c.ID, c.Credit)
103			}
104			if _, dup := s.courseByID[c.ID]; dup {
105				return fmt.Errorf("课程编号 %s 重复", c.ID)
106			}
107			s.courses = append(s.courses, c)
108			s.courseByID[c.ID] = c
109		}
110	
111		// 学生
112		for _, st := range d.Students {
113			if st == nil || st.ID == "" {
114				return errors.New("存在没有编号的学生记录")
115			}
116			if _, dup := s.studentByID[st.ID]; dup {
117				return fmt.Errorf("学生编号 %s 重复", st.ID)
118			}
119			s.students = append(s.students, st)
120			s.studentByID[st.ID] = st
121		}
122	
123		// 要求
124		for _, r := range d.Requirements {
125			if r == nil {
126				return errors.New("存在空的课程要求记录")
127			}
128			if r.StudentID == "" || r.ID == "" {
129				return errors.New("存在缺少学生编号或要求编号的课程要求")
130			}
131			if _, ok := s.studentByID[r.StudentID]; !ok {
132				return fmt.Errorf("要求 %s 引用了不存在的学生 %s", r.ID, r.StudentID)
133			}
134			if _, ok := s.courseByID[r.CourseID]; !ok {
135				return fmt.Errorf("学生 %s 的要求 %s 引用了不存在的课程 %s",
136					r.StudentID, r.ID, r.CourseID)
137			}
138			key := reqKey(r.StudentID, r.ID)
139			if _, dup := s.reqByKey[key]; dup {
140				return fmt.Errorf("学生 %s 的要求编号 %s 重复", r.StudentID, r.ID)
141			}
142			dk := dupKey(r.StudentID, r.CourseID)
143			if other, dup := s.reqByDup[dk]; dup {
144				return fmt.Errorf("学生 %s 就课程 %s 存在重复要求 %s 与 %s",
145					r.StudentID, r.CourseID, other, r.ID)
146			}
147			s.requirements = append(s.requirements, r)
148			s.reqByKey[key] = r
149			s.reqByDup[dk] = r.ID
150		}
151	
152		// 修读
153		usedSeq := map[int]bool{}
154		for _, e := range d.Enrollments {
155			if e == nil {
156				return errors.New("存在空的修读记录")
157			}
158			if e.StudentID == "" || e.ID == "" {
159				return errors.New("存在缺少学生编号或修读编号的修读记录")
160			}
161			if _, ok := s.studentByID[e.StudentID]; !ok {
162				return fmt.Errorf("修读 %s 引用了不存在的学生 %s", e.ID, e.StudentID)
163			}
164			r := s.reqByKey[reqKey(e.StudentID, e.ReqID)]
165			if r == nil {
166				return fmt.Errorf("学生 %s 的修读 %s 引用了不存在的要求 %s",
167					e.StudentID, e.ID, e.ReqID)
168			}
169			if e.Term == "" {
170				return fmt.Errorf("学生 %s 的修读 %s 缺少学期", e.StudentID, e.ID)
171			}
172			switch e.Result {
173			case Enrolled, Passed, Failed:
174			default:
175				return fmt.Errorf("学生 %s 的修读 %s 含非法结果 %q", e.StudentID, e.ID, e.Result)
176			}
177			if e.Result == Enrolled {
178				if e.ResultSeq != 0 {
179					return fmt.Errorf("修读 %s 尚未提交结果却带有结果序号", e.ID)
180				}
181			} else {
182				if e.ResultSeq <= 0 {
183					return fmt.Errorf("修读 %s 已提交结果但缺少结果序号", e.ID)
184				}
185				if usedSeq[e.ResultSeq] {
186					return fmt.Errorf("结果提交序号 %d 重复，记录已损坏", e.ResultSeq)
187				}
188				usedSeq[e.ResultSeq] = true
189			}
190			key := reqKey(e.StudentID, e.ID)
191			if _, dup := s.enrByKey[key]; dup {
192				return fmt.Errorf("学生 %s 的修读编号 %s 重复", e.StudentID, e.ID)
193			}
194			s.enrollments = append(s.enrollments, e)
195			s.enrByKey[key] = e
196		}
197	
198		// 免修（被拒绝的申请允许指向当时不存在的要求）
199		approvedReq := map[string]string{} // student+"\x00"+req -> waiverID
200		for _, w := range d.Waivers {
201			if w == nil {
202				return errors.New("存在空的免修记录")
203			}
204			if w.StudentID == "" || w.ID == "" {
205				return errors.New("存在缺少学生编号或免修编号的免修记录")
206			}
207			if _, ok := s.studentByID[w.StudentID]; !ok {
208				return fmt.Errorf("免修 %s 引用了不存在的学生 %s", w.ID, w.StudentID)
209			}
210			switch w.Status {
211			case WaiverApproved, WaiverRejected, WaiverRevoked:
212			default:
213				return fmt.Errorf("学生 %s 的免修 %s 含非法状态 %q", w.StudentID, w.ID, w.Status)
214			}
215			if w.Status == WaiverApproved {
216				if w.Basis == "" {
217					return fmt.Errorf("有效免修 %s 缺少依据", w.ID)
218				}
219				rk := reqKey(w.StudentID, w.ReqID)
220				if s.reqByKey[rk] == nil {
221					return fmt.Errorf("有效免修 %s 指向不存在的要求 %s", w.ID, w.ReqID)
222				}
223				if other, dup := approvedReq[rk]; dup {
224					return fmt.Errorf("学生 %s 的要求 %s 同时存在有效免修 %s 与 %s",
225						w.StudentID, w.ReqID, other, w.ID)
226				}
227				approvedReq[rk] = w.ID
228			}
229			key := reqKey(w.StudentID, w.ID)
230			if _, dup := s.waiverByKey[key]; dup {
231				return fmt.Errorf("学生 %s 的免修编号 %s 重复", w.StudentID, w.ID)
232			}
233			s.waivers = append(s.waivers, w)
234			s.waiverByKey[key] = w
235		}
236	
237		if d.NextResultSeq < 0 {
238			return errors.New("结果提交序号计数器为负数")
239		}
240		for seq := range usedSeq {
241			if seq > d.NextResultSeq {
242				return fmt.Errorf("结果提交序号计数器 %d 小于已有序号 %d", d.NextResultSeq, seq)
243			}
244		}
245		s.nextResultSeq = d.NextResultSeq
246		return nil
247	}
248	
249	// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
250	// 避免写到一半时损坏原文件。
251	func (s *Store) Save(path string) (err error) {
252		data := fileData{
253			Version:       recordVersion,
254			Courses:       s.courses,
255			Students:      s.students,
256			Requirements:  s.requirements,
257			Enrollments:   s.enrollments,
258			Waivers:       s.waivers,
259			NextResultSeq: s.nextResultSeq,
260		}
261		buf, err := json.MarshalIndent(&data, "", "  ")
262		if err != nil {
263			return fmt.Errorf("无法序列化记录：%w", err)
264		}
265		buf = append(buf, '\n')
266	
267		dir := filepath.Dir(path)
268		if dir == "" {
269			dir = "."
270		}
271		tmp, err := os.CreateTemp(dir, ".credit-*.tmp")
272		if err != nil {
273			return fmt.Errorf("无法在 %s 创建临时记录文件：%w", dir, err)
274		}
275		tmpName := tmp.Name()
276		defer func() {
277			if err != nil {
278				tmp.Close()
279				os.Remove(tmpName)
280			}
281		}()
282		if _, err = tmp.Write(buf); err != nil {
283			return fmt.Errorf("写入记录文件失败：%w", err)
284		}
285		if err = tmp.Sync(); err != nil {
286			return fmt.Errorf("写入记录文件失败：%w", err)
287		}
288		if err = tmp.Close(); err != nil {
289			return fmt.Errorf("写入记录文件失败：%w", err)
290		}
291		if err = os.Chmod(tmpName, 0o600); err != nil {
292			return fmt.Errorf("设置记录文件权限失败：%w", err)
293		}
294		if err = os.Rename(tmpName, path); err != nil {
295			return fmt.Errorf("保存记录文件 %s 失败：%w", path, err)
296		}
297		return nil
298	}
