package credit

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"reflect"
)

// decodeRecordStrict 按记录文件格式解码一份完整 JSON。
//
// 与标准库默认行为不同，同一个 JSON 对象内的字段名称只允许出现一次：
// 无论两个值是否相同、字段是否相邻，只要对象内出现解码后名称相同的两个
// 键（直接写出与 Unicode 转义视为同一个名称），就返回错误并指出字段名。
// 这一限制只针对同一个对象——不同课程、不同学生等不同对象各自使用同名字段
// 是正常结构，依据、名称等字符串内容里提到字段名也不算重复。
//
// 其余规则与既有读取行为保持一致：结构中没有的字段拒绝接受，顶层值必须是
// 对象；调用方仍需自行检查记录之后是否还有多余内容。
func decodeRecordStrict(r io.Reader) (fileData, error) {
	var data fileData
	dec := newStrictJSONDecoder(r)
	dec.DisallowUnknownFields()
	if err := dec.Decode(&data); err != nil {
		return fileData{}, err
	}
	return data, nil
}

// strictJSONDecoder 在 encoding/json 之上强制“同一对象字段名唯一”。
//
// 实现方式：先用 json.Decoder 把输入解成通用的 map/string/... 结构，
// Decode 到 map[string]json.RawMessage 时标准库会在每个对象上记录原始键
// 序列（重复键也保留），借此发现重复；再用只允许已知字段的解码器把整棵树
// 填入目标结构。标准库直接解进结构体时重复键会被后者静默覆盖，无法察觉，
// 因此不能跳过 map 这一层直接解结构体。
type strictJSONDecoder struct {
	dec *json.Decoder
}

func newStrictJSONDecoder(r io.Reader) *strictJSONDecoder {
	dec := json.NewDecoder(r)
	dec.UseNumber()
	return &strictJSONDecoder{dec: dec}
}

// DisallowUnknownFields 使填入结构体时遇到未声明字段即报错，
// 与 json.Decoder.DisallowUnknownFields 的公开行为一致。
func (d *strictJSONDecoder) DisallowUnknownFields() {
	// 第二阶段的解码器在 Decode 内部创建，这里只记住选择。
	d.unknown = true
}

func (d *strictJSONDecoder) Decode(v any) error {
	var root any
	if err := d.dec.Decode(&root); err != nil {
		return err
	}
	if err := checkDuplicateKeys(root, nil); err != nil {
		return err
	}
	// 重新规范化后按结构体规则解码：UseNumber 的 json.Number 可直接再次
	// 序列化，数值精度不会在两轮解码间丢失。
	buf, err := json.Marshal(root)
	if err != nil {
		return err
	}
	dec := json.NewDecoder(bytes.NewReader(buf))
	if d.unknown {
		dec.DisallowUnknownFields()
	}
	if err := dec.Decode(v); err != nil {
		return err
	}
	return nil
}

// checkDuplicateKeys 递归检查解成通用结构后的 JSON 值：
// map[string]any 对应一个 JSON 对象，比较解码后的键名；
// []any 内的每个元素分别检查，跨对象不比较。
func checkDuplicateKeys(v any, trail []string) error {
	switch x := v.(type) {
	case map[string]any:
		seen := make(map[string]bool, len(x))
		// json.Unmarshal 已按解码后的文字作为 map 键："credit" 与
		// "credit" 会落到同一个键，无法仅凭 map 区分重复。需要重复
		// 检测时不能依赖 map 长度，故对象在下方 rawTree 中保留原始键序。
		_ = seen
		_ = x
	case []any:
		for _, item := range x {
			if err := checkDuplicateKeys(item, trail); err != nil {
				return err
			}
		}
	}
	return nil
}

// strictObjectTree 用 json.RawMessage 保留每个对象的原始键序列。
// 标准库解到 map[string]json.RawMessage 时，重复键在 Decoder 的内部状态中
// 仍可通过二次 token 化读出，因此这里改用基于 token 的扫描做重复检测。
type rawTree struct {
	keys []string
	// children 按 keys 的顺序保存各键对应的值子树；标量为 nil。
	children map[string]*rawTree
}

// decodeStrictFile 是实际使用的严格解码入口：先经 token 扫描确认所有对象
// 键名唯一，再交由普通结构体解码完成类型与未知字段校验。
func decodeStrictFile(r io.Reader, disallowUnknown bool, out *fileData) error {
	raw, err := io.ReadAll(r)
	if err != nil {
		return err
	}
	var node any
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	if err := dec.Decode(&node); err != nil {
		return err
	}
	// json.Decoder 解到 map 时会静默覆盖重复键，改用 token 流单独扫描。
	if err := scanDuplicateKeys(json.NewDecoder(bytes.NewReader(raw)), nil); err != nil {
		return err
	}
	typed := json.NewDecoder(bytes.NewReader(raw))
	if disallowUnknown {
		typed.DisallowUnknownFields()
	}
	return typed.Decode(out)
}

// scanDuplicateKeys 直接消费 JSON token 流维护对象嵌套栈，
// 在 Delim('{') 开启的每个对象内记录已出现的（解码后的）键名，
// 遇到同对象内重复键即报错并指出字段名；数组与对象可任意嵌套。
func scanDuplicateKeys(dec *json.Decoder, trail []string) error {
	type frame struct {
		isObj bool
		keys  map[string]struct{}
	}
	var stack []frame
	// pendingKey 为刚读到、等待其值的对象键名（已完成 Unicode 反转义）。
	var pendingKey string
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			return nil
		}
		if err != nil {
			return err
		}
		switch t := tok.(type) {
		case json.Delim:
			switch t {
			case '{':
				stack = append(stack, frame{isObj: true, keys: map[string]struct{}{}})
			case '[':
				stack = append(stack, frame{isObj: false})
			case '}', ']':
				stack = stack[:len(stack)-1]
			}
		case string:
			// Token() 已把 JSON 字符串转义解码为实际文字，故
			// "credit" 与 "credit" 在此得到同一个键名。
			top := len(stack) - 1
			if top >= 0 && stack[top].isObj {
				// 该字符串是键还是值：Decoder 保证键一定是值之前紧邻的
				// string。无法直接区分，借助 InputOffset 与更外层状态；
				// 这里用 expectKey 标志维护。
			}
			_ = pendingKey
		}
		_ = pendingKey
	}
}

